///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(((String(dma_basicComInfo.get("listTpClssCd")) === "02") ? "상장법인" : "심사진행법인")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_basicComInfo.get("comNm")) + "(" + String(dma_basicComInfo.get("isurCd")) + ")"; } },
        { childId: "__rb2", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_basicComInfo.get("mktTpNm")); } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_basicComInfo.get("secugrpNm")); } },
        { childId: "__rb5", attr: "label", fn: function () { return String(((String(dma_basicComInfo.get("listTpClssCd")) === "02") ? "우회상장보고서 제출일" : "예비심사청구서 제출일")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_42", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "c_otherwise_47", fn: function(){ return (!(((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'))); } }, { id: "if_listTpClssCd_3", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "tr_86", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "if_listTpClssCd_4", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '06' || (dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '07'); } }, { id: "tr_93", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '06' || (dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '07'); } }, { id: "c_when_105", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '02'); } }, { id: "c_when_114", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '06'); } }, { id: "c_when_123", fn: function(){ return ((dma_basicComInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.listTpClssCd"); })()) === '07'); } }, { id: "btn_doSave", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '30' || ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '35'|| ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "listProcsStatCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listProcsStatCd")) === '37'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_listTpClssCd", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("listTpClssCd"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.onload();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51110.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51110' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.saveYn = '' + dma_dataList.get("save_yn") + '';

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil51110.onpageload' });
    }
};


