/**
 * @method
 * @name scwin.doSave
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.doSave = async function () {
    /* sdd-asis-lifecycle:begin doSave — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let msg = '작성된 내용을 저장하시겠습니까?';
    let methodName = 'saveMergeInfo';
    if (scwin.saveYn === 'Y') {
        msg = '작성된 내용으로 수정하시겠습니까?';
        methodName = 'editMergeInfo';
    }
    if (await $c.win.confirm(msg)) {
        if (await scwin.isValidate()) {
            scwin.form.action = '/listInvstg/listPrelmInvstgEtc.do';
            $c.util.getComponent('dma_doSaveReq').set('method', methodName);
            await scwin.tx_doSave();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isCheckRadio
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.isCheckRadio = function (ver) {
    /* sdd-asis-lifecycle:begin isCheckRadio — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < ver.getItemCount(); i++) {
        if (ver[i].checked) {
            return true;
        }
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isValidate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.isValidate = async function () {
    /* sdd-asis-lifecycle:begin isValidate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('cal_bodResolDd').getValue() == null ? '' : String($c.util.getComponent('cal_bodResolDd').getValue())) === '') {
        await $c.win.alert('이사회 결의일은 필수 입니다.');
        return false;
    }
    if (($c.util.getComponent('cal_mergeDd').getValue() == null ? '' : String($c.util.getComponent('cal_mergeDd').getValue())) === '') {
        await $c.win.alert('합병기일은 필수 입니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_comNm0').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm0').getValue())) === '') {
        await $c.win.alert('기업인수목적회사의 기업명은 필수 입니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_comNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm1').getValue())) === '') {
        await $c.win.alert('비상장법인의 기업명은 필수 입니다.');
        return false;
    }
    if (($c.util.getComponent('ipt_comNm2').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm2').getValue())) === '') {
        await $c.win.alert('우회상장 후 법인의 기업명은 필수 입니다.');
        return false;
    }
    if (!(String(($c.util.getComponent('rd_nparvalstkYn0'))?.getValue?.() ?? "") !== "")) {
        await $c.win.alert('기업인수목적회사의 무액면주식여부는 필수 입니다.');
        return false;
    }
    if (!(String(($c.util.getComponent('rd_nparvalstkYn1'))?.getValue?.() ?? "") !== "")) {
        await $c.win.alert('비상장법인의 무액면주식여부는 필수 입니다.');
        return false;
    }
    if (!(String(($c.util.getComponent('rd_nparvalstkYn2'))?.getValue?.() ?? "") !== "")) {
        await $c.win.alert('우회상장 후 법인의 무액면주식여부는 필수 입니다.');
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


